using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using Fanex.Tarus.LiveCasino.DataAccess.MoveAccount;
using Fanex.Tarus.LiveCasino.Entities;
using Fanex.Tarus.LiveCasino.Entities.MoveAccount;
using Sunplus.Accounting.Core.Extensions;

namespace Fanex.Tarus.LiveCasino.Business.MoveAccount
{
    public class MoveAccountManager:IMoverAccountManager
    {
        private IMoveAccountDataAccess _moveAccountDataAccess;
        public MoveAccountManager ():this (null)
        {}

        public MoveAccountManager (IMoveAccountDataAccess moveAccountDataAccess)
        {
            _moveAccountDataAccess = moveAccountDataAccess ?? new MoveAccountDataAccess();
        }

        Result MoveMaster(MoveAccountInfo moveAccountInfo)
        {
            Result result = new Result();

            try
            {
               result = _moveAccountDataAccess.CheckMoveMaster(moveAccountInfo);
               if(result.IsSuccess)
               {
                   result = _moveAccountDataAccess.MoveMaster(moveAccountInfo);

                   LogMoveAccountInfo log = new LogMoveAccountInfo(LogActions.TP_User_Customer_MoveMaster_Update);
                   log.ErrCode = result.Key;
                   log.ErrMsg = result.Value;
                   log.MoveAccount = moveAccountInfo;
                   log.UserId = moveAccountInfo.SignupBy;

                   _moveAccountDataAccess.WriteLog(log);
               }
            }
            catch (Exception ex)
            {
                LogExtensions.ExceptionHandler(ex);
            }
            return result;
        }


        Result MoveAgent(MoveAccountInfo moveAccountInfo)
        {
            Result result = new Result();

            try
            {
                result = _moveAccountDataAccess.CheckMoveAgent(moveAccountInfo);
                if (result.IsSuccess)
                {
                    result = _moveAccountDataAccess.MoveAgent(moveAccountInfo);

                    LogMoveAccountInfo log = new LogMoveAccountInfo(LogActions.TP_User_Customer_MoveAgent_Update);
                    log.ErrCode = result.Key;
                    log.ErrMsg = result.Value;
                    log.MoveAccount = moveAccountInfo;
                    log.UserId = moveAccountInfo.SignupBy;

                    _moveAccountDataAccess.WriteLog(log);
                }
            }
            catch (Exception ex)
            {
                LogExtensions.ExceptionHandler(ex);
            }
            return result;
        }

        public Result Move(MoveAccountInfo moveAccountInfo, bool isMoveAgent)
        {
            Result result = new Result();

            try
            {
                if(isMoveAgent)
                {
                   result = MoveAgent(moveAccountInfo);
                }
                else
                {
                    result = MoveMaster(moveAccountInfo);
                }
                
            }
            catch (Exception ex)
            {
                LogExtensions.ExceptionHandler(ex);
            }

            return result;
        }


        public Result Rollback(MoveAccountInfo moveAccountInfo,  bool isMoveAgent)
        {
            Result result = new Result();
            try
            {
                LogMoveAccountInfo log = null;

                moveAccountInfo.RollbackCustId = moveAccountInfo.MovedCustId;
            
                if(isMoveAgent)
                {
                    result = _moveAccountDataAccess.RollbackMoveAgent(moveAccountInfo);
                    log = new LogMoveAccountInfo(LogActions.TP_User_Customer_MoveAgent_Rollback)
                              {
                                  ErrCode = result.Key,
                                  ErrMsg = result.Value,
                                  UserId = moveAccountInfo.UserId,
                                  MoveAccount = moveAccountInfo
                              };
                }
                else
                {
                    result = _moveAccountDataAccess.RollbackMoveMaster(moveAccountInfo);
                    log = new LogMoveAccountInfo(LogActions.TP_User_Customer_MoveMaster_Rollback)
                              {
                                  ErrCode = result.Key,
                                  ErrMsg = result.Value,
                                  UserId = moveAccountInfo.UserId,
                                  MoveAccount = moveAccountInfo
                              };
                              
                }


                _moveAccountDataAccess.WriteLog(log);
            }
            catch (Exception ex)
            {
                LogExtensions.ExceptionHandler(ex);
            }
            return result;
        }
    }
}
